&gt;&gt; &lt;a href="/cdn-cgi/l/email-protection" class="__cf_email__" data-cfemail="adc7d8cfc8838383edc2ddc8c3ccc483cec2c0"&gt;[email&#160;protected]&lt;/a&gt;
