&lt;h1&gt;
&lt;span class="subject"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=subject:%22Re%5C%3A+%5C%5Bblink%5C-dev%5C%5D+Intent+to+Ship%5C%3A+Add+javascriptURLs+option+to+SanitizerConfig+and+Sanitizer%22&amp;o=newest" rel="nofollow"&gt;&lt;span itemprop="name"&gt;Re: [blink-dev] Intent to Ship: Add javascriptURLs option to SanitizerConfig and Sanitizer&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
&lt;/h1&gt;
&lt;p class="darkgray font13"&gt;
&lt;span class="sender pipe"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=from:%22%27Daniel+Vogelheim%27+via+blink%5C-dev%22" rel="nofollow"&gt;&lt;span itemprop="author" itemscope itemtype="http://schema.org/Person"&gt;&lt;span itemprop="name"&gt;'Daniel Vogelheim' via blink-dev&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
