&lt;h1&gt;
&lt;span class="subject"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=subject:%22%5C%5Bblink%5C-dev%5C%5D+Re%5C%3A+Intent+to+Experiment%5C%3A+Connection+Allowlists+Embedded+Enforcement%22&amp;o=newest" rel="nofollow"&gt;&lt;span itemprop="name"&gt;[blink-dev] Re: Intent to Experiment: Connection Allowlists Embedded Enforcement&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
