&lt;div class="msgHead"&gt; &lt;h1&gt; &lt;span class="subject"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=subject:%22Re%5C%3A+%5C%5Bblink%5C-dev%5C%5D+Intent+to+Ship%5C%3A+closest%5C-corner+and+farthest%5C-corner+radii+for+circle%5C%28%5C%29+and+ellipse%5C%28%5C%29+basic+shapes%22&amp;o=newest" rel="nofollow"&gt;&lt;span itemprop="name"&gt;Re: [blink-dev] Intent to Ship: closest-corner and farthest-corner radii for circle() and ellipse() basic shapes&lt;/span&gt;&lt;/a&gt;&lt;/span&gt; &lt;/h1&gt; &lt;p class="darkgray font13"&gt; &lt;span class="sender pipe"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=from:%22Mike+Taylor%22" rel="nofollow"&gt;&lt;span itemprop="author" itemscope itemtype="http://schema.org/Person"&gt;&lt;span itemprop="name"&gt;Mike Taylor&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt; &lt;span class="date"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=date:20260902" rel="nofollow"&gt;Wed, 02 Sep 2026 11:44:12 -0700&lt;/a&gt;&lt;/span&gt; &lt;/p&gt; &lt;/div&gt;&lt;div itemprop="articleBody" class="msgBody"&gt;
